/* 프로토 5 LLM 래퍼 — 소관은 **생성**뿐이다 (분류 없음, GDD R11).
     ① turn()  — 한 수: 길드마스터의 대사 + 의뢰인의 대사
     ② react() — 반응 한마디: 의뢰인이 **내 책상을 보고** 흘리는 말

   3회차 수정 (플레이 판정 반영):
   - 말투 계약 — 직업별 어미를 예문과 함께 고정. "존댓말/반말을 섞지 마라" 명시
   - 칸별 기왕력 — 이미 말한 사실을 주고 **부정 금지**. "모른다"는 "거기까지"로

   react()의 절대 규칙: 의뢰인은 플레이어가 **한 것**에만 반응한다. **안 한 것**
   (빈칸)은 절대 입에 올리지 않는다 (GDD "창구는 끝까지 침묵한다"). */

const LLM_OK = !!(window.PROTO_CONFIG && window.PROTO_CONFIG.apiKey
  && !window.PROTO_CONFIG.apiKey.startsWith('sk-...'));

async function chat(messages, max = 400) {
  const res = await fetch('https://api.openai.com/v1/chat/completions', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json',
               Authorization: 'Bearer ' + window.PROTO_CONFIG.apiKey },
    body: JSON.stringify({ model: window.PROTO_CONFIG.model, messages,
      temperature: 0.9, max_tokens: max, response_format: { type: 'json_object' } }),
  });
  if (!res.ok) throw new Error('LLM ' + res.status);
  return JSON.parse((await res.json()).choices[0].message.content);
}

/* 말투 계약 (3회차) — 성격만으론 어미가 오락가락했다. 예문과 함께 못박는다 */
const PERSONA = {
  '주민': { who:'가난한 마을 주민. 겁이 많고 말이 짧다.',
    tone:'더듬거리는 존댓말만 쓴다. (예) "그, 그게… 저는 잘 모르겠습니다요."' },
  '상인': { who:'셈이 빠른 장사꾼. 손해를 싫어하고 값 이야기를 자주 꺼낸다.',
    tone:'싹싹하고 능란한 존댓말만 쓴다. (예) "아이고, 그게 다 돈 아니겠습니까."' },
  '관리': { who:'지방 관리. 절차와 기록 뒤에 선다.',
    tone:'딱딱한 문어체 존댓말만 쓴다. (예) "해당 건은 확인된 바 없습니다."' },
  '귀족': { who:'몰락해 가는 귀족. 에두르고 체면을 신경 쓴다.',
    tone:'격식 있는 하오체로만 일관한다. (예) "그건 곤란하오. 가문의 일이니."' },
  '갱단': { who:'뒷골목 사람. 말이 짧고 눈을 피하지 않는다.',
    tone:'짧은 반말만 쓴다. (예) "몰라. 그런 건 왜 물어."' },
};
const toneRule = occ => [
  `의뢰인 직업: ${occ}. ${PERSONA[occ].who}`,
  `★ 말투 계약: ${PERSONA[occ].tone}`,
  '  **존댓말과 반말을 절대 섞지 마라. 첫 대사부터 마지막 대사까지 같은 어미를 유지하라.**',
].join('\n');

/* ---------------- ① 한 수 ---------------- */

const OUTCOME = {
  told:   '의뢰인이 순순히 말한다. **주어진 「밝혀진 사실」을 반드시 자기 입으로 말한다.** 부정하거나 얼버무리지 마라.',
  unknown:'의뢰인이 거기서부터는 정말 모른다. 미안해하거나 머쓱해한다. **어떤 새 사실도 말하지 마라.**',
  evade:  '의뢰인이 알면서 피한다. **무엇을 숨기는지는 절대 말하지 마라.** 화제를 돌리거나 짧게 자른다.',
  hintFail:'건네받은 이야기가 자기 일과 이어지지 않는다. 여전히 모른다. **새 사실을 말하지 마라.**',
  leverFail:'들이댄 이야기가 자기 아픈 곳이 아니다. 담담히 넘긴다. **새 사실을 말하지 마라.**',
};

const VERB = {
  ask:   '그 칸의 내용을 묻는다',
  press: '이미 들은 것보다 더 자세히 캐묻는다',
  hint:  '자기가 아는 이야기를 **건네주어 기억을 일깨우려 한다**',
  lever: '자기가 아는 이야기를 **꺼내 지목하며 압박한다** (무례하지 않게, 직업인으로서)',
};

async function turn(ctx) {
  const sys = [
    `길드 접수창구 장면을 쓴다.`,
    toneRule(ctx.occ),
    '두 사람의 대사를 하나씩 쓴다. 한국어, 각각 **최대 2문장·70자 이내**.',
    '',
    '★ 역할을 절대 섞지 마라:',
    '  - "me"   = **길드마스터(플레이어)의 말.** 서류를 채우려는 접수원이다. 묻는 쪽.',
    '  - "them" = **의뢰인의 말.** 도움을 청하러 온 사람이다. 답하는 쪽.',
    '    (나쁜 예) 의뢰인이 "그 생김새가 궁금합니다" ← 의뢰인은 이미 겪은 사람이다',
    '',
    '★ 절대 규칙 ①: **「밝혀진 사실」로 주어진 것 외의 구체적 사실(색·수·이름·장소·현상)을',
    '  지어내지 마라.** 「화제」는 물어볼 거리의 **이름일 뿐 내용이 아니다.**',
    '  「밝혀진 사실」이 없으면 **의뢰인은 어떤 새 사실도 말하지 않는다.** 모른다/피한다만 한다.',
    '  (나쁜 예) 모른다면서 "소리는 들었습니다" ← 새 사실이다. 금지.',
    '',
    '★ 절대 규칙 ②: 「길드마스터가 꺼낸 이야기」가 주어지면 **"me"는 반드시 그 이야기를',
    '  자기 입으로 말해야 한다.** 다른 질문으로 바꾸지 마라.',
    '  (좋은 예) "제가 알기로 트롤은 발가락이 셋이라고 합니다만."',
    '',
    '★ 절대 규칙 ③: 「이미 말한 사실」이 주어지면 **절대 부정하지 마라.** "모른다"고 답할',
    '  때도 이미 말한 것은 인정한 채 **"내가 아는 건 거기까지"** 라는 태도여야 한다.',
    '  (나쁜 예) 발자국을 봤다고 말해 놓고 "저는 아무것도 모릅니다" ← 자기 말을 뒤집었다. 금지.',
    '  (좋은 예) "발자국을 본 게 전부입니다. 그 이상은 저도…"',
    '',
    'JSON만 출력: {"me": "...", "them": "..."}',
  ].join('\n');

  const user = [
    `길드마스터가 하려는 것: ${VERB[ctx.verb]}`,
    `화제(내용이 아니라 이름): ${ctx.topic || '(없음)'}`,
    ctx.prior && ctx.prior.length
      ? `이 화제에 대해 의뢰인이 **이미 말한 사실** (부정 금지): ${ctx.prior.map(f=>`"${f}"`).join(' / ')}` : '',
    ctx.material ? `길드마스터가 꺼낸 이야기: "${ctx.material}"` : '',
    `의뢰인의 반응: ${OUTCOME[ctx.outcome]}`,
    ctx.revealed ? `밝혀진 사실(이 내용을 반드시 말할 것): ${ctx.revealed}` : '',
    '',
    '최근 대화:',
    ...(ctx.history.slice(-6).map(h => `${h.who}: ${h.text}`) || []),
  ].filter(Boolean).join('\n');

  const out = await chat([{ role:'system', content: sys }, { role:'user', content: user }]);
  window.__lastRaw = { user, out };
  return { me: String(out.me || '').slice(0, 200), them: String(out.them || '').slice(0, 200) };
}

/* ---------------- ② 반응 한마디 ---------------- */

const REACT = {
  assertBlind: c => `길드마스터가 의뢰서에 「${c.label}」이라고 적어 넣는 것을 봤다.
그 칸의 내용은 네가 **정말 모르는** 것이다. 확인도 부정도 할 수 없다.
모른다는 태도로, 종이를 곁눈질하며 한마디.`,
  assertSore: c => `길드마스터가 의뢰서에 「${c.label}」이라고 적어 넣는 것을 봤다.
그 칸의 내용은 네가 **알면서 숨기는** 것이다. 속이 뜨끔하지만 **아무것도 인정하지 마라.**
비확정적인 한마디만. (예: 그렇게 적으신다면야…)`,
  assertOff: c => `길드마스터가 의뢰서에 「${c.label}」이라고 적어 넣는 것을 봤다.
네가 보기엔 이 일과 동떨어진 소리다. 갸웃하는 한마디.`,
  assertSeen: c => `길드마스터가 의뢰서에 「${c.label}」이라고 적어 넣는 것을 봤다.
네가 이미 말해 준 내용과 겹치는 칸이다. 종이를 보며 담담히 한마디. **새 사실 금지.**`,
  silence: c => `길드마스터가 아무 말 없이 너를 기다린다. 침묵이 어색하다.
침묵을 못 이기고 **자기 처지 걱정**을 흘리는 한마디.
걱정의 결: ${ {'손익':'돈과 장사 손해','절차':'기록과 보고, 윗선','체면':'소문과 평판'}[c.lev] || '별다른 약점이 없다 — 날씨나 피로 같은 무난한 잡담'}.
**사건에 관한 새 사실은 절대 금지.**`,
  stampHand: () => `길드마스터가 도장에 손을 얹었다. 접수가 끝나 간다.
초조하거나 안도하는 한마디. **서류에 무엇이 비었는지·무엇을 안 물었는지는 절대 언급 금지.**`,
  bookPeek: () => `길드마스터가 말없이 책을 뒤적이고 있다. 그 모습이 궁금하거나 불안하다.
책에 대해 묻거나 눈치를 보는 한마디.`,
  annoyed: () => `길드마스터가 또 헛다리를 짚었다. 인내가 줄어든다.
짜증이나 피로를 누르는 한마디. **새 사실 금지.**`,
};

async function react(ctx) {
  const sys = [
    `길드 접수창구. 너는 의뢰인이다.`,
    toneRule(ctx.occ),
    '지금 길드마스터의 **행동을 보고** 흘리는 짧은 반응 한마디를 쓴다.',
    '한국어, **1문장, 45자 이내.** 질문에 대한 대답이 아니라 혼잣말에 가까운 반응이다.',
    '',
    '★ 절대 규칙: 사건에 관한 **새 사실(색·수·이름·장소·현상)을 지어내지 마라.**',
    '★ 절대 규칙: 서류의 **빈칸이나 안 물어본 것을 언급하지 마라.**',
    '',
    'JSON만 출력: {"them": "..."}',
  ].join('\n');
  const user = [
    REACT[ctx.kind](ctx),
    '',
    '최근 대화:',
    ...(ctx.history.slice(-4).map(h => `${h.who}: ${h.text}`) || []),
  ].join('\n');
  const out = await chat([{ role:'system', content: sys }, { role:'user', content: user }], 150);
  return { them: String(out.them || '').slice(0, 120) };
}

window.LLM = { ok: LLM_OK, turn, react };
